"""Arithmetic expression evaluator (recursive descent, Approach A in SPEC.md).

Grammar (precedence lowest to highest):

    expression := term (('+' | '-') term)*
    term       := unary (('*' | '/') unary)*
    unary      := '-' unary | power
    power      := primary ('^' unary)?          # right-associative; RHS may be signed
    primary    := NUMBER | IDENT | '(' expression ')'

Note that unary minus sits between term and power, so ``-2^2`` parses as
``-(2^2)``, while ``2 ^ -1`` still works because the exponent is parsed as a
``unary``.
"""

from __future__ import annotations

import re
from collections.abc import Mapping

__all__ = ["ExprError", "evaluate"]


class ExprError(Exception):
    """Raised for syntax errors, unknown variables, or division by zero."""


_TOKEN_RE = re.compile(
    r"""
    \s*(?:
        (?P<number>(?:\d+\.\d*|\.\d+|\d+))
      | (?P<ident>[A-Za-z_][A-Za-z0-9_]*)
      | (?P<op>[-+*/^()])
    )
    """,
    re.VERBOSE,
)


def _tokenize(text: str) -> list[tuple[str, str]]:
    tokens: list[tuple[str, str]] = []
    pos = 0
    end = len(text)
    while pos < end:
        match = _TOKEN_RE.match(text, pos)
        if match is None:
            rest = text[pos:].lstrip()
            if not rest:
                break
            raise ExprError(f"unexpected character {rest[0]!r} at position {pos}")
        kind = match.lastgroup
        assert kind is not None
        tokens.append((kind, match.group(kind)))
        pos = match.end()
    tokens.append(("end", ""))
    return tokens


class _Parser:
    def __init__(self, tokens: list[tuple[str, str]], variables: Mapping[str, object]):
        self._tokens = tokens
        self._pos = 0
        self._variables = variables

    # -- token helpers -----------------------------------------------------
    def _peek(self) -> tuple[str, str]:
        return self._tokens[self._pos]

    def _advance(self) -> tuple[str, str]:
        token = self._tokens[self._pos]
        self._pos += 1
        return token

    def _accept_op(self, *ops: str) -> str | None:
        kind, value = self._peek()
        if kind == "op" and value in ops:
            self._advance()
            return value
        return None

    def _expect_op(self, op: str) -> None:
        if self._accept_op(op) is None:
            kind, value = self._peek()
            found = "end of input" if kind == "end" else repr(value)
            raise ExprError(f"expected {op!r} but found {found}")

    # -- grammar -----------------------------------------------------------
    def parse(self) -> float:
        value = self._expression()
        kind, text = self._peek()
        if kind != "end":
            raise ExprError(f"unexpected token {text!r}")
        return value

    def _expression(self) -> float:
        value = self._term()
        while (op := self._accept_op("+", "-")) is not None:
            rhs = self._term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def _term(self) -> float:
        value = self._unary()
        while (op := self._accept_op("*", "/")) is not None:
            rhs = self._unary()
            if op == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ExprError("division by zero")
                value = value / rhs
        return value

    def _unary(self) -> float:
        if self._accept_op("-") is not None:
            return -self._unary()
        return self._power()

    def _power(self) -> float:
        base = self._primary()
        if self._accept_op("^") is not None:
            exponent = self._unary()
            try:
                result = base ** exponent
            except ZeroDivisionError as exc:
                raise ExprError("division by zero") from exc
            except OverflowError as exc:
                raise ExprError("result too large") from exc
            if isinstance(result, complex):
                raise ExprError("result is not a real number")
            return float(result)
        return base

    def _primary(self) -> float:
        kind, text = self._advance()
        if kind == "number":
            return float(text)
        if kind == "ident":
            try:
                return float(self._variables[text])
            except KeyError:
                raise ExprError(f"unknown variable {text!r}") from None
            except (TypeError, ValueError) as exc:
                raise ExprError(f"variable {text!r} is not numeric") from exc
        if kind == "op" and text == "(":
            value = self._expression()
            self._expect_op(")")
            return value
        found = "end of input" if kind == "end" else repr(text)
        raise ExprError(f"expected a number, variable or '(' but found {found}")


def evaluate(text: str, variables: dict | None = None) -> float:
    """Evaluate an arithmetic expression and return the result as a float.

    Raises :class:`ExprError` on any syntax error, unknown variable, or
    division by zero.
    """
    tokens = _tokenize(text)
    if tokens[0][0] == "end":
        raise ExprError("empty expression")
    return _Parser(tokens, variables or {}).parse()
